-- 01-locations.sql
-- V5-SPACETENANCYKEY-001, multi-space step 2.1 (plan V204 §2.1, §3 row 2.1). File 01 of 25.
-- public.locations gains its Space key. Stamp 5.3.13-tenancykey-001-locations.
-- GENERATED by generate.mjs from owner-classes.json. Edit those, run `node generate.mjs --write`;
--   tenancykey.test.js reds on any difference.
--
-- WHAT, in one transaction:
--   0. LOCK locations (ACCESS EXCLUSIVE), so the owner census and the DDL see the same rows.
--   1. The guard ($pregate$): the env, the database's fingerprint, the Space the DEFAULT names, and the owner
--      pre-gate: every distinct owner value of every row (soft-deleted rows included) must be in this env's
--      section of owner-classes.json; the owner column is created_by.
--      Anything else refuses, naming the values, and changes nothing.
--   2. ADD COLUMN workspace_id uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001'.
--      A constant default is metadata only: existing rows read it from pg_attribute (atthasmissing); no row is
--      rewritten (rehearsed: filenode kept).
--   3. FOREIGN KEY (workspace_id) -> public.spaces(id) ON DELETE RESTRICT NOT VALID, single column (C-BLOCK:
--      spaces_delete_guard reads single-column keys only). No row scan. Step 2.3 validates it.
--   4. Comments and the stamp.
-- ENV. Run with psql -v env=prod|staging (scripts/tenancykey-apply.py passes it). Without -v env psql cannot
--   parse the set_config line and nothing runs. Any other value, or a database without that env's
--   schema_version fingerprint, refuses.
-- DEPLOYED CODE. No deployed writer names workspace_id on this table, so every INSERT takes the DEFAULT, which
--   is a Space, and no UPDATE changes the column (README.md "Arming census").
-- LOCKS. ACCESS EXCLUSIVE on locations and SHARE ROW EXCLUSIVE on spaces, to COMMIT; catalog changes plus one
--   scan of locations for the census. lock_timeout 5s: a wait fails fast (55P03) having changed nothing.
--   The runner refuses at :58-:02 and 07:00-08:00 UTC.
-- RE-RUN. With the stamp present nothing changes. A workspace_id column or a key into spaces without the stamp
--   refuses: something else made it.
-- ROLLBACK: 0r-rollback.sql.

BEGIN;

SET LOCAL lock_timeout = '5s';
SELECT set_config('tenancykey.env', :'env', true) AS env \gset tk_

LOCK TABLE public.locations IN ACCESS EXCLUSIVE MODE;

-- ── 1. The guard (read-only: the runner's --dry-run runs this block alone). ───────────────────────────────
DO $pregate$
DECLARE
  v_env text := current_setting('tenancykey.env', true);
  v_bad text;
  v_def text;
BEGIN
  IF v_env IS NULL OR v_env NOT IN ('prod', 'staging') THEN
    RAISE EXCEPTION 'v5-tenancykey-001 01 (locations) refused, nothing changed: env is %, not prod or staging.', coalesce(quote_literal(v_env), 'unset')
      USING HINT = 'Run it with psql -v env=prod or -v env=staging (scripts/tenancykey-apply.py does).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.schema_version
                  WHERE version = CASE v_env WHEN 'prod' THEN '4.0.0-pot-001' ELSE '4.23.9-cascadesweep-001-rollback' END)
     OR EXISTS (SELECT 1 FROM public.schema_version
                 WHERE version = CASE v_env WHEN 'prod' THEN '4.23.9-cascadesweep-001-rollback' ELSE '4.0.0-pot-001' END) THEN
    RAISE EXCEPTION 'v5-tenancykey-001 01 (locations) refused, nothing changed: this database does not carry the % fingerprint (owner-classes.json "fingerprint").', v_env
      USING HINT = 'The -v env value names the other database. Check which URL this is before anything else.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.schema_version WHERE version = '5.3.13-tenancykey-001-locations') THEN
    RAISE NOTICE 'v5-tenancykey-001 01 (locations): stamp 5.3.13-tenancykey-001-locations present; nothing to check.';
    RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.spaces WHERE id = '00000000-0000-0000-0000-000000000001') THEN
    RAISE EXCEPTION 'v5-tenancykey-001 01 (locations) refused, nothing changed: the DEFAULT''s Space 00000000-0000-0000-0000-000000000001 is not a row of public.spaces.';
  END IF;

  WITH allowed (env, match, val, class) AS (
    VALUES
    ('prod', 'exact', 'user_3D2gM0hIl03gjW3JM2DjtPzm0jI', 'dave'),
    ('prod', 'exact', 'user_3E2xA85kQhr1vSZhiv4W1GLudJV', 'jen'),
    ('prod', 'exact', 'system', 'system'),
    ('prod', 'exact', 'user_3D7uvqWjyxdq3jgVwTZs0mKT7Xd', 'system_clerk_sub'),
    ('prod', 'exact', 'user_3CxBEbOgG0fmeGmB6D0ohTju0wv', 'dave_dev'),
    ('prod', 'like', 'rescue-intake-%', 'managed_rescue_intake'),
    ('prod', 'like', 'data-audit-%', 'managed_data_audit'),
    ('prod', 'like', 'data-correction-%', 'managed_data_correction'),
    ('prod', 'exact', 'cal1-seed', 'pipeline_cal1_seed'),
    ('prod', 'exact', 'migration:v4-harvweightest-001', 'pipeline_harvweightest'),
    ('prod', 'exact', 'res008-backfill', 'pipeline_res008'),
    ('prod', 'exact', 'agent:mainsync13-20260928', 'pipeline_mainsync13'),
    ('staging', 'exact', 'user_3D2gM0hIl03gjW3JM2DjtPzm0jI', 'dave'),
    ('staging', 'exact', 'user_3E2xA85kQhr1vSZhiv4W1GLudJV', 'jen'),
    ('staging', 'exact', 'system', 'system'),
    ('staging', 'exact', 'user_3D7uvqWjyxdq3jgVwTZs0mKT7Xd', 'system_clerk_sub'),
    ('staging', 'exact', 'user_3CxBEbOgG0fmeGmB6D0ohTju0wv', 'dave_dev'),
    ('staging', 'like', 'rescue-intake-%', 'managed_rescue_intake'),
    ('staging', 'like', 'data-audit-%', 'managed_data_audit'),
    ('staging', 'like', 'data-correction-%', 'managed_data_correction'),
    ('staging', 'exact', 'cal1-seed', 'pipeline_cal1_seed'),
    ('staging', 'exact', 'migration:v4-harvweightest-001', 'pipeline_harvweightest'),
    ('staging', 'exact', 'res008-backfill', 'pipeline_res008'),
    ('staging', 'exact', 'agent:mainsync13-20260928', 'pipeline_mainsync13'),
    ('staging', 'like', '%int-test-%', 'integration_fixture'),
    ('staging', 'null', NULL, 'staging_null_location_owner')
  ), owners (col, val, n) AS (
    SELECT 'created_by' AS col, t.created_by AS val, count(*) AS n FROM public.locations t GROUP BY t.created_by
  )
  SELECT string_agg(format('%s %s: %s row(s)', o.col, coalesce(quote_literal(o.val), 'NULL'), o.n), ', '
                    ORDER BY o.col, o.val)
    INTO v_bad
    FROM owners o
   WHERE NOT EXISTS (SELECT 1 FROM allowed a
                      WHERE a.env = v_env
                        AND ((a.match = 'exact' AND o.val = a.val)
                          OR (a.match = 'like' AND o.val LIKE a.val)
                          OR (a.match = 'null' AND o.val IS NULL)));
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'v5-tenancykey-001 01 (locations) refused, nothing changed: owner value(s) outside the % section of owner-classes.json: %', v_env, v_bad
      USING HINT = 'Class each value in owner-classes.json with its reason, regenerate and re-review; or correct the row. Never widen a pattern to fit.';
  END IF;
END $pregate$;

-- ── 2-3. The column and the key, once. ──────────────────────────────────────────────────────────────────
DO $ddl$
DECLARE
  v_bad text;
  v_def text;
BEGIN
  IF EXISTS (SELECT 1 FROM public.schema_version WHERE version = '5.3.13-tenancykey-001-locations') THEN
    RAISE NOTICE 'v5-tenancykey-001 01 (locations): already applied; nothing changed.';
    RETURN;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_attribute a
               JOIN pg_class c ON c.oid = a.attrelid
               JOIN pg_namespace n ON n.oid = c.relnamespace
              WHERE n.nspname = 'public' AND c.relname = 'locations'
                AND a.attname = 'workspace_id' AND NOT a.attisdropped) THEN
    RAISE EXCEPTION 'v5-tenancykey-001 01 (locations) refused, nothing changed: public.locations.workspace_id exists but stamp 5.3.13-tenancykey-001-locations does not.'
      USING HINT = 'Something other than this file added it. Find what, before anything else.';
  END IF;
  SELECT string_agg(k.conname, ', ' ORDER BY k.conname) INTO v_bad
    FROM pg_constraint k
    JOIN pg_class c ON c.oid = k.conrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_class f ON f.oid = k.confrelid
    JOIN pg_namespace fn ON fn.oid = f.relnamespace
   WHERE n.nspname = 'public' AND c.relname = 'locations' AND k.contype = 'f'
     AND fn.nspname = 'public' AND f.relname = 'spaces' AND k.conname = 'locations_workspace_id_fkey';
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'v5-tenancykey-001 01 (locations) refused, nothing changed: public.locations already has key % into spaces.', v_bad;
  END IF;

  ALTER TABLE public.locations
    ADD COLUMN workspace_id uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001';
  ALTER TABLE public.locations
    ADD CONSTRAINT locations_workspace_id_fkey
    FOREIGN KEY (workspace_id) REFERENCES public.spaces (id) ON DELETE RESTRICT NOT VALID;
END $ddl$;

-- ── 4. Comments and the stamp. ───────────────────────────────────────────────────────────────────────────
COMMENT ON COLUMN public.locations.workspace_id IS
  'V5-SPACETENANCYKEY-001 (v5-tenancykey-001 01, step 2.1). The Space this row belongs to. The DEFAULT is the one Space until writers stamp it (2.2, 4.3); RESTRICT key into spaces, validated by step 2.3.';
COMMENT ON CONSTRAINT locations_workspace_id_fkey ON public.locations IS
  'V5-SPACETENANCYKEY-001 (v5-tenancykey-001 01, step 2.1). A row''s Space is a row of public.spaces. RESTRICT: a Space with rows here cannot be deleted. NOT VALID until step 2.3.';

INSERT INTO public.schema_version (version, description)
VALUES ('5.3.13-tenancykey-001-locations',
        'TENANCYKEY locations: V5-SPACETENANCYKEY-001 (multi-space step 2.1, file 01 of 25). '
        'ADD COLUMN workspace_id uuid NOT NULL DEFAULT the one Space; locations_workspace_id_fkey -> spaces(id) '
        'ON DELETE RESTRICT NOT VALID. Owner pre-gate: owner-classes.json, section '
        || current_setting('tenancykey.env') || '.')
ON CONFLICT (version) DO NOTHING;

COMMIT;
